var header = gridObj.getColumnId(cInd);
if (stage == 0) {
    if(header == "MODULE"){
        if( gridObj.cells(rId, gridObj.getColIndexById('PARENT')).getValue() != "*"){
            return false;
        }
    }
    return true;
} else if (stage == 1) {
    return true;
} else if (stage == 2) {
    if (header == 'MODULE') {
        var tmp = [];
        var allItems = gridObj.getAllSubItems().split(',');
        for (var idx in allItems) {
            var v = gridObj.cells(allItems[idx], gridObj.getColIndexById('MODULE')).getValue();
            if (tmp.indexOf(v) + 1) {
                Alert(Sepoa.cache.text.get('AD_120.MESSAGE_0002'));
                return false;
            } else {
                tmp.push(v);
            }
        }

        var subItems = gridObj.getSubItems(rId).split(',');
        for (var idx in subItems) {
            if (subItems[idx] != "") {
                gridObj.cells(subItems[idx], gridObj.getColIndexById('PARENT')).setValue(nValue);
            }
        }
    } else if (header == 'DESCRIPTION') {
        gridObj.cells(rId, gridObj.getColIndexById('TREE_ID')).setValue(nValue);
    }
    return true;
}
return false;


