gridObj.editStop();
var selected = gridObj.getSelectedRows('SELECTED');
if (selected.length <= 0) {
    Alert(Sepoa.cache.text.get('MESSAGE.1004'));
    return;
}

var deleteRows = [];
function rDelete(rId, obj) {
    var subItems = gridObj.getSubItems(rId).split(',');
    for (var idx in subItems) {
        if (subItems[idx] != "") {
            rDelete(subItems[idx], obj);
        }
    }
    deleteRows.push(rId);
    if (obj.indexOf(rId) + 1) {
        obj.slice(obj.indexOf(rId), 1);
    }
}

while (selected.length > 0) {
    rDelete(selected.pop(), selected);
}

var deleteRowNames = ['<br/>'];
var moduleNameCin = gridObj.getColIndexById('DESCRIPTION');
for(var idx in deleteRows) {
	var name = gridObj.cells(deleteRows[idx], moduleNameCin).getValue();
	deleteRowNames.push(name);
}

var msg = Sepoa.cache.text.get('AD_120.MESSAGE_0006') + deleteRowNames.join('<br/>');
Confirm(msg, function(flag) {
	if(flag) {
		var selectedCin = gridObj.getColIndexById('SELECTED');
		var storageCin = gridObj.getColIndexById('STORAGE');
		deleteRows.forEach(function(element, idx) {
			if(gridObj.cells(element, storageCin).getValue() != '0') {
				gridObj.cells(element, selectedCin).setChecked(true);
			} else {
				gridObj.cells(element, selectedCin).setChecked(false);
			}
		});

		var params = [];
        params.push('mode=doSave');
        params.push('PROCESS_ID=sepoa.svc.admin.AD_120');
        params.push('METHOD=doDelete');
        gridObj.postTransaction(window.CONTEXT_NAME + '/SepoaGrid.sux', params, 'SELECTED');
	}
});


var subItems = gridObj.getSubItems(rId).split(',');

var cnt = 0;
for (var idx in subItems) {
    if (subItems[idx] != "") {
        gridObj.cells(subItems[idx], gridObj.getColIndexById('SORT')).setValue(++cnt);
        setSortNumber(subItems[idx]);
    }
}
